/* Primary CSS file inside the search-bar shadowRoot */

@import url("chrome://messenger/skin/widgets.css");

:host {
  --search-padding: 6px;
  --search-button-show: flex;
  --search-buttons-padding: 28px;
}

form {
  position: relative;
  min-block-size: max(1.2em, calc(1.2em + 2 * var(--search-padding)));
  block-size: 100%;
  color: var(--search-bar-color);
}

input {
  position: absolute;
  inset: 0;
  inline-size: 100%;
  block-size: 100%;
  font-size: 1rem;
  color: var(--search-bar-color);
  border: 1px solid var(--search-bar-border-color);
  border-radius: var(--button-border-radius);
  padding-inline: var(--search-padding) var(--search-buttons-padding);
  background-color: var(--search-bar-background);
